mapper.select:
select d.TRADE_ID as tradeId, /**交易编号**/ d.BUSI_TYPE as busiTypeCode, /**业务类型Code**/ d.BUSI_TYPE as busiType, /**业务类型**/
acct.ACCT_SUBJECT_ID as prodId, acct.ACCT_SUBJECT_NAME as prodAbbr, zc.FINPROD_ID as assetId, /**资产代码**/ zc.FINPROD_ABBR as assetAbbr,/**资产简称**/ zc.profit_type profitTypeCode,/**收益类型Code**/ zc.profit_type profitType,/**收益类型**/ d.PS as psCode,/**交易方向Code**/ d.PS as ps,/**交易方向**/ d.TRADE_MARKET as tradeMarketCode,/**交易场所Code**/ d.TRADE_MARKET as tradeMarket,/**交易场所**/ d.INV_AIM as invAimCode,/**投资目的Code**/ d.INV_AIM as invAim,/**投资目的**/ to_char(d.vdate,'yyyy-mm-dd') as vDate,/**发生日 - 取交易日期**/ to_char(d.mDate,'yyyy-mm-dd') as mDate,/*交割日*/ to_char(d.TRADE_DATE,'yyyy-mm-dd') as tradeDate,/**发生日 - 取交易日期**/ to_char(d.settle_date,'yyyy-mm-dd') as settleDate,/*交割日*/ to_char(d.cprice_Date,'yyyy-mm-dd') as cpriceDate,/*净值日*/ d.CCY as ccyCode,/**交易币种Code**/ d.CCY as ccy,/**交易币种**/ d.PRIN_AMT as prinAmt,/**券面总额/交易本金**/ d.UNIT_CPRICE as unitCprice, /**单位净价**/ d.UNIT_FPRICE as unitFprice, /**单位全价**/ d.share_amt shareAmt,/*交易份额*/ d.CPRICE_AMT as cpriceAmt, /**净价总额**/ d.unit_INT as unitInt, /**应收利息总额 - 单位分红利息**/ d.INT_AMT as intAmt, /**应收利息总额 - 取利息总额**/ d.FPRICE_AMT as fpriceAmt, /**全价总额**/ d.FEE_AMT as feeAmt, /**总交易费用**/ tdf.FEE_AMT as tdFeeAmt,/**通道费**/ /**当交易方向是红利再投时 交易金额取值是 (交易份额*单位净价),否则取值交易金额**/ ( CASE WHEN d.PS='T12' THEN (d.SHARE_AMT)*(d.UNIT_CPRICE) ELSE d.TRADE_AMT END )as tradeAmt,/**交易金额**/ d.YIELD*100 as yield, /**到期收益率**/ d.EXER_YIELD as exerYield, /**行权收益率**/ d.TRADE_STATUS as tradeStatusCode, /**交易状态Code**/ d.TRADE_STATUS as tradeStatus, /**交易状态**/ d.counter_id counterId,/*交易对手*/
d.is_out_trade as isOutTradeCode,/* 是否外部交易Code */ d.is_out_trade as isOutTrade,/* 是否外部交易 */ d.trader trader,/*交易员*/ d.chl_id chlId,/*通道*/ ( CASE WHEN instr('T08,T09,T22,T23', d.ps) >0 THEN to_char(cash.VDATE,'yyyy-mm-dd') ELSE NULL END ) as interestBeginDate,/*计息开始日*/ ( CASE WHEN instr('T08,T09,T22,T23', d.ps) >0 THEN to_char(cash.MDATE,'yyyy-mm-dd') ELSE NULL END ) as interestEndDate,/*计息截止日*/ ( CASE WHEN instr('T08,T09,T22,T23', d.ps) >0 THEN to_char(cash.PAY_DATE,'yyyy-mm-dd') ELSE NULL END ) as planPayDate,/*计划支付日*/
0.0 returnAmt /*退款金额*/ from trd_PRODUCT_DEAL d inner join FIN_PRODUCT zc on zc.finprod_id = d.finprod_id
left join TRD_PRODUCT_DEAL_ADD e on d.trade_id = e.trade_id
inner join BOK_DEAL_ACCOUNTING deal on deal.BUSI_NO = d.TRADE_ID inner join BOK_BOOKSET book on deal.BOOKSET_ID = book.BOOKSET_ID inner join BOK_ACCT_SUBJECT_INFO acct on acct.ACCT_SUBJECT_ID = book.ACCT_SUBJECT_ID and acct.ACCT_SUBJECT_TYPE = book.ACCT_SUBJECT_TYPE left join TRD_TRADE_FEE_DETAIL tdf on tdf.trade_id = d.trade_id and tdf.fee_type = 'B09' left join MST_CUSTOMER_INFO cust_out on cust_out.customer_id = d.counter_id left join FIN_PRODUCT cust_in on cust_in.finprod_id = d.counter_id left join FIN_CASH_PLAN cash on cash.FINPROD_ID = d.finprod_id and cash.PAY_DATE = d.TRADE_DATE/**现金流计划表**/ where 1=1
and d.TRADE_ID = #{paTradeId}
and acct.ACCT_SUBJECT_ID = #{prodId}
and (zc.FINPROD_ID LIKE '%'||#{paAsset}||'%' or zc.FINPROD_ABBR LIKE '%'||#{paAsset}||'%' ) and d.BUSI_TYPE in
#{queryType}
and d.BUSI_TYPE in
#{paBusiType}
and book.BOOKSET_ID in
#{bookSetId}
and d.PS in
#{paPs}
and d.TRADE_DATE >= to_date(#{tradeDateBegin},'yyyy-mm-dd')
and d.TRADE_DATE <= to_date(#{tradeDateEnd},'yyyy-mm-dd')
and zc.profit_type=#{profitType}

select A.tradeid tradeId, /*交易编号*/ A.finprodid prodId, /*投资主体代码*/ A.finprodabbr prodAbbr, /*投资主体名称*/ A.finprodtype feeTypeName, /*费用交易类型*/
listagg(a.fee_type) within GROUP (order by (a.fee_type)) feeTypeCode, A.tradedate tradeDate, /*交易日*/ sum(A.fpriceamt) tradeAmt, /*交易金额*/ A.ccy ccy, /*币种*/ A.ccyCode ccyCode, /*币种*/ A.tradestatus tradeStatus, /*交易状态*/ A.busiTypeCode busiTypeCode, /**业务类型Code**/ A.tradestatusCode tradestatusCode, A.remark remark /*备注*/ from ( select tpd.trade_id tradeid, /*交易编号*/
acct.ACCT_SUBJECT_ID as finprodid, acct.ACCT_SUBJECT_NAME as finprodabbr, ttfd.fee_type, case when ttfd.fee_type = 'TAX0102' or ttfd.fee_type = 'TAX0202' or ttfd.fee_type = 'TAX0302' then '增值税' else ttfd.fee_type end finprodtype, /*交易类型*/ to_char(tpd.trade_date,'yyyy-MM-dd') tradeDate, /*交易日*/ ttfd.fee_amt fpriceamt, /*交易金额*/ tpd.ccy ccy, /*币种*/ tpd.ccy ccyCode, tpd.trade_status tradestatus, /*交易状态*/ tpd.trade_status tradestatusCode, tpd.BUSI_TYPE as busiTypeCode, /**业务类型Code**/ '' remark /*备注*/ from TRD_PRODUCT_DEAL tpd
LEFT JOIN TRD_PRODUCT_DEAL_ADD EXT ON TPD.TRADE_ID=EXT.TRADE_ID
inner join BOK_DEAL_ACCOUNTING deal on deal.BUSI_NO = tpd.TRADE_ID inner join BOK_BOOKSET book on deal.BOOKSET_ID = book.BOOKSET_ID inner join BOK_ACCT_SUBJECT_INFO acct on acct.ACCT_SUBJECT_ID = book.ACCT_SUBJECT_ID and acct.ACCT_SUBJECT_TYPE = book.ACCT_SUBJECT_TYPE left join TRD_TRADE_FEE_DETAIL ttfd on tpd.trade_id = ttfd.trade_id where 1=1 and tpd.finprod_type = 'C07'
and tpd.TRADE_ID LIKE '%'||#{paTradeId}||'%'
and tpd.TRADE_ID LIKE '%'||#{paAsset}||'%' and tpd.BUSI_TYPE in
#{queryType}
and tpd.BUSI_TYPE in
#{paBusiType}
and book.BOOKSET_ID in
#{bookSetId}
and tpd.PS in
#{paPs}
and tpd.TRADE_DATE >= to_date(#{tradeDateBegin},'yyyy-mm-dd')
and tpd.TRADE_DATE <= to_date(#{tradeDateEnd},'yyyy-mm-dd')
and fp.profit_type=#{profitType}
) A group by A.tradeid, A.finprodid, A.finprodabbr, A.tradedate, A.ccy, A.tradestatus, A.remark, A.finprodtype, A.busiTypeCode, A.tradestatusCode, A.ccyCode

select tpd.trade_id tradeId, /*交易编号*/
acct.ACCT_SUBJECT_ID as prodId, acct.ACCT_SUBJECT_NAME as prodAbbr, tpd.finprod_type as feeTypeNameCode, /*交易类型*/ tpd.finprod_type finprodTypeName, /*交易类型*/ to_char(tpd.trade_date,'yyyy-MM-dd') tradeDate, /*交易日*/ tpd.trade_amt tradeAmt, /*交易金额*/ tpd.ccy ccy, /*币种*/ tpd.ccy as ccyCode, /*币种*/ tpd.BUSI_TYPE busiTypeCode, /**业务类型Code**/ tpd.trade_status tradeStatus, /*交易状态*/ tpd.trade_status as tradeStatusCode, /*交易状态*/ '' remark /*备注*/ from TRD_PRODUCT_DEAL tpd
left join TRD_PRODUCT_DEAL_ADD ext on tpd.trade_id = ext.trade_id
inner join BOK_DEAL_ACCOUNTING deal on deal.BUSI_NO = tpd.TRADE_ID inner join BOK_BOOKSET book on deal.BOOKSET_ID = book.BOOKSET_ID inner join BOK_ACCT_SUBJECT_INFO acct on acct.ACCT_SUBJECT_ID = book.ACCT_SUBJECT_ID and acct.ACCT_SUBJECT_TYPE = book.ACCT_SUBJECT_TYPE where tpd.busi_type = '18' and tpd.finprod_type != 'C07'
and tpd.TRADE_ID LIKE '%'||#{paTradeId}||'%'
and tpd.TRADE_ID LIKE '%'||#{paAsset}||'%' and tpd.BUSI_TYPE in
#{queryType}
and tpd.BUSI_TYPE in
#{paBusiType}
and book.BOOKSET_ID in
#{bookSetId}
and tpd.PS in
#{paPs}
and tpd.TRADE_DATE >= to_date(#{tradeDateBegin},'yyyy-mm-dd')
and tpd.TRADE_DATE <= to_date(#{tradeDateEnd},'yyyy-mm-dd')
and fp.profit_type=#{profitType}

select T0.TRADE_ID as tradeId, /**交易编号**/ acct.ACCT_SUBJECT_ID as prodId, acct.ACCT_SUBJECT_NAME as prodAbbr, T0.BUSI_TYPE as busiTypeCode, /**业务类型Code**/ T0.BUSI_TYPE as busiType, /**业务类型**/
T0.ORDER_TYPE as type, /*收划款类型*/ to_char(T0.SETTLE_DATE,'yyyy-mm-dd') as settleDat,/**收划款日期**/ T0.SETTLE_AMT as settleAmt,/**收划款金额**/ T0.CCY as ccyCode,/**交易币种Code**/ T0.CCY as ccy, /**币种**/ DECODE(T0.PS,'01',T4.ACCT_NAME,T5.ACCT_NAME)AS myAcctName, /**收款账户户名**/ DECODE(T0.PS,'01',T0.MY_ACCT_NO,T0.COUNTER_ACCT_NO) AS myAcctNo, /**收款账户账号**/ DECODE(T0.PS,'01',T5.ACCT_NAME,T4.ACCT_NAME) AS counterAcctName,/**付款账户户名**/ DECODE(T0.PS,'01',T0.COUNTER_ACCT_NO,T0.MY_ACCT_NO) AS counterAcctNo, /**付款账户账号**/ T0.SETTLE_STATUS AS status /**收划款状态**/ from STL_ORDERS T0 /**结算指令表**/ left join TRD_PRODUCT_DEAL T1 on T0.TRADE_ID = T1.TRADE_ID /**金融产品交易表**/ inner join BOK_DEAL_ACCOUNTING deal on ( deal.BUSI_NO = T1.TRADE_ID OR deal.BUSI_NO = T0.ORDER_ID ) inner join BOK_BOOKSET book on deal.BOOKSET_ID = book.BOOKSET_ID inner join BOK_ACCT_SUBJECT_INFO acct on acct.ACCT_SUBJECT_ID = book.ACCT_SUBJECT_ID and acct.ACCT_SUBJECT_TYPE = book.ACCT_SUBJECT_TYPE left join STL_CAPACCT_INFO T4 on T0.MY_ACCT_NO = T4.ACCT_NO /**清算账户表**/ left join STL_CAPACCT_INFO T5 on T0.COUNTER_ACCT_NO = T5.ACCT_NO /**清算账户表**/ where 1=1 and ORDER_TYPE in ('1001', '1002', '1007', '1008','1009', '1010')
and T0.TRADE_ID LIKE '%'||#{paTradeId}||'%'
and T1.TRADE_ID LIKE '%'||#{paAsset}||'%' and T0.BUSI_TYPE in
#{queryType}
and (T0.BUSI_TYPE in
#{paBusiType}
or '19' in
#{paBusiType}
)
and book.BOOKSET_ID in
#{bookSetId}
and T0.PS in
#{paPs}
and T0.SETTLE_DATE >= to_date(#{tradeDateBegin},'yyyy-mm-dd')
and T0.SETTLE_DATE <= to_date(#{tradeDateEnd},'yyyy-mm-dd')
order by T0.TRADE_ID

select d.TRADE_ID as tradeId, /**交易编号**/ d.BUSI_TYPE as busiTypeCode, /**业务类型Code**/ d.BUSI_TYPE as busiType, /**业务类型**/ acct.ACCT_SUBJECT_ID as prodId, acct.ACCT_SUBJECT_NAME as prodAbbr, zc.FINPROD_ID as assetId, /**资产代码**/ zc.FINPROD_ABBR as assetAbbr,/**资产简称**/ d.PS as psCode,/**交易方向Code**/ d.PS as ps,/**交易方向**/ d.TRADE_MARKET as tradeMarketCode,/**交易场所Code**/ d.TRADE_MARKET as tradeMarket,/**交易场所**/ d.INV_AIM as invAimCode,/**投资目的Code**/ d.INV_AIM as invAim,/**投资目的**/ to_char(d.TRADE_DATE,'yyyy-mm-dd') as tradeDate,/**发生日 - 取交易日期**/ d.CCY as ccyCode,/**币种Code**/ d.CCY as ccy,/**币种**/ d.PRIN_AMT as prinAmt,/**交易本金**/ d.INT_AMT as intAmt,/**交易利息**/ d.TRADE_AMT as tradeAmt,/**交易金额**/ d.TRADE_STATUS as tradeStatusCode, /**交易状态Code**/ d.TRADE_STATUS as tradeStatus /**交易状态**/ from trd_PRODUCT_DEAL d inner join FIN_PRODUCT zc on zc.finprod_id = d.finprod_id inner join BOK_DEAL_ACCOUNTING deal on deal.BUSI_NO = d.TRADE_ID inner join BOK_BOOKSET book on deal.BOOKSET_ID = book.BOOKSET_ID inner join BOK_ACCT_SUBJECT_INFO acct on acct.ACCT_SUBJECT_ID = book.ACCT_SUBJECT_ID and acct.ACCT_SUBJECT_TYPE = book.ACCT_SUBJECT_TYPE where 1=1
and d.TRADE_ID LIKE '%'||#{paTradeId}||'%'
and (zc.FINPROD_ID LIKE '%'||#{paAsset}||'%' or zc.FINPROD_ABBR LIKE '%'||#{paAsset}||'%' )
and d.BUSI_TYPE in
#{queryType}
and d.BUSI_TYPE in
#{paBusiType}
and book.BOOKSET_ID in
#{bookSetId}
and d.PS in
#{paPs}
and d.TRADE_DATE >= to_date(#{tradeDateBegin},'yyyy-mm-dd')
and d.TRADE_DATE <= to_date(#{tradeDateEnd},'yyyy-mm-dd')
and zc.profit_type=#{profitType}
